@Component
public class OrderListener {

    // 1) 값만
    @KafkaListener(topics = "order.placed.v1", groupId = "inventory")
    public void handle(OrderPlaced event) {
        inventoryService.decrease(event);
    }

    // 2) 레코드 전체 (파티션·오프셋·헤더가 필요할 때)
    @KafkaListener(topics = "order.placed.v1", groupId = "audit")
    public void handleRecord(ConsumerRecord<String, OrderPlaced> record) {
        log.info("{}-{}@{}", record.topic(), record.partition(), record.offset());
    }

    // 3) 애너테이션으로 꺼내기
    @KafkaListener(topics = "order.placed.v1", groupId = "mail")
    public void handleWithHeaders(
            @Payload OrderPlaced event,
            @Header(KafkaHeaders.RECEIVED_KEY) String key,
            @Header(name = "traceId", required = false) String traceId) {
        mailService.send(event, traceId);
    }

    // 4) 수동 커밋 (7.4절)
    @KafkaListener(topics = "order.placed.v1", groupId = "settle")
    public void handleManual(OrderPlaced event, Acknowledgment ack) {
        settle(event);
        ack.acknowledge();
    }

    // 5) 배치로 받기
    @KafkaListener(topics = "order.placed.v1", groupId = "bulk",
                   containerFactory = "batchFactory")
    public void handleBatch(List<OrderPlaced> events, Acknowledgment ack) {
        repository.saveAll(events);      // 배치 INSERT
        ack.acknowledge();
    }
}
